// K115 stage 5a: standalone emblem scenes (docs/design/K115_stage5.md).
//
// buildEmblemGraph turns an EmblemId into a TangleGraph of closed strands
// from the offline point tables (src/core/emblem_data.ts, generated by
// .claude/probes/K115/gen_emblems.mjs). It reuses the text builder's
// machinery by export, not by copy: assignOverUnder (core/text_graph.ts)
// assigns overFirst phases, and the TURN resample rule re-declares the
// text builder's MAX_EDGE_LU (core/text_graph.ts:27) as in stage 3.
//
// Determinism (K108): this file uses only +, -, *, / and Math.sqrt via
// hypot2. No other Math functions. Tables are decimal literals.

import { EMBLEM_DEFS } from "./emblem_data";
import type { EmblemDef, EmblemId } from "./emblem_data";
import { NODE_TYPE } from "./types";
import type { Node, Strand, TangleGraph } from "./types";
import { assignOverUnder } from "./text_graph";
import { hypot2 } from "../util/det_math";

export type { EmblemDef, EmblemId } from "./emblem_data";
export { EMBLEM_DEFS, EMBLEM_IDS } from "./emblem_data";

type Pt = [number, number];

// Default emblem diameter (LU across the authored bounds' larger axis).
export const EMBLEM_DIA = 10;
// TURN chains: at most this per edge (the text builder's MAX_EDGE_LU,
// re-declared; stage 3's attachTitle did the same for its pieces).
const MAX_EDGE_LU = 1.4;
// Coincidence tolerance in canonical units, squared (far below 6 dp).
const COINCIDE_TOL2 = 0.000000000001; // 1e-12

export function isEmblemId(value: string): value is EmblemId {
  return Object.hasOwn(EMBLEM_DEFS, value);
}

function d2(a: Pt, b: Pt): number {
  const x = a[0] - b[0];
  const y = a[1] - b[1];
  return x * x + y * y;
}

function lerpPt(a: Pt, b: Pt, t: number): Pt {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
}

export function buildEmblemGraph(
  id: EmblemId,
  opts?: { diameter?: number }
): TangleGraph {
  const def: EmblemDef | undefined = EMBLEM_DEFS[id];
  if (!def) throw new Error(`unknown emblem: ${String(id)}`);
  const diameter =
    opts && opts.diameter !== undefined && opts.diameter > 0
      ? opts.diameter
      : EMBLEM_DIA;

  // Scale canonical points to the target diameter about the bounds centre,
  // so the authored bounds become `diameter` LU across the larger axis.
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  for (const loop of def.loops) {
    for (const p of loop) {
      if (p[0] < minX) minX = p[0];
      if (p[0] > maxX) maxX = p[0];
      if (p[1] < minY) minY = p[1];
      if (p[1] > maxY) maxY = p[1];
    }
  }
  const extent = Math.max(maxX - minX, maxY - minY);
  if (!(extent > 0)) throw new Error(`emblem ${id}: degenerate bounds`);
  const scale = diameter / extent;
  const cx = (minX + maxX) / 2;
  const cy = (minY + maxY) / 2;
  const toLu = (p: readonly [number, number]): Pt => [
    (p[0] - cx) * scale,
    (p[1] - cy) * scale,
  ];

  // One node per distinct canonical point (exact coincidence merges the
  // passes at each crossing; tolerance in canonical units).
  const distinct: Pt[] = []; // canonical
  const loopDistinct: number[][] = def.loops.map((loop) =>
    loop.map((p) => {
      const cp: Pt = [p[0], p[1]];
      for (let i = 0; i < distinct.length; i++) {
        if (d2(distinct[i], cp) <= COINCIDE_TOL2) return i;
      }
      distinct.push(cp);
      return distinct.length - 1;
    })
  );

  interface FNode {
    pos: Pt;
    type: (typeof NODE_TYPE)[keyof typeof NODE_TYPE];
  }
  const fNodes: FNode[] = distinct.map((p) => ({
    pos: toLu(p),
    type: NODE_TYPE.TURN,
  }));
  interface FEdge {
    a: number;
    b: number;
  }
  const fEdges: FEdge[] = [];

  // TURN edges between consecutive points, wrapping each loop closed;
  // resample any edge longer than MAX_EDGE_LU with TURN nodes.
  const strandCycles: Array<{ nodes: number[]; edges: number[] }> = [];
  loopDistinct.forEach((cyc) => {
    const cycleNodes: number[] = [];
    const cycleEdges: number[] = [];
    for (let ri = 0; ri < cyc.length; ri++) {
      const a = cyc[ri];
      const b = cyc[(ri + 1) % cyc.length];
      if (ri === 0) cycleNodes.push(a);
      const aPos = fNodes[a].pos;
      const bPos = fNodes[b].pos;
      const len = hypot2(bPos[0] - aPos[0], bPos[1] - aPos[1]);
      let chunks = Math.ceil(len / MAX_EDGE_LU - 0.000000001);
      if (chunks < 1) chunks = 1;
      let prev = a;
      for (let c = 1; c < chunks; c++) {
        const ni = fNodes.length;
        fNodes.push({ pos: lerpPt(aPos, bPos, c / chunks), type: NODE_TYPE.TURN });
        cycleEdges.push(fEdges.length);
        fEdges.push({ a: prev, b: ni });
        cycleNodes.push(ni);
        prev = ni;
      }
      cycleEdges.push(fEdges.length);
      fEdges.push({ a: prev, b });
      if (ri + 1 < cyc.length) cycleNodes.push(b);
    }
    strandCycles.push({ nodes: cycleNodes, edges: cycleEdges });
  });

  // A point shared by 2 passes (4 incident edge-ends) is a CROSSING; any
  // other authored/resampled point is degree 2, a TURN.
  const degree = fNodes.map(() => 0);
  for (const e of fEdges) {
    degree[e.a] += 1;
    degree[e.b] += 1;
  }
  let crossingCount = 0;
  fNodes.forEach((n, i) => {
    if (degree[i] === 4) {
      n.type = NODE_TYPE.CROSSING;
      crossingCount += 1;
    } else if (degree[i] === 2) {
      n.type = NODE_TYPE.TURN;
    } else {
      throw new Error(`emblem ${id}: node degree ${degree[i]} (not 2 or 4)`);
    }
  });
  if (crossingCount !== def.crossings) {
    throw new Error(
      `emblem ${id}: built ${crossingCount} crossings, table says ${def.crossings}`
    );
  }

  const nodeIds = fNodes.map((_, i) => `sn${i}`);
  const nodes = new Map<string, Node>();
  fNodes.forEach((n, i) => {
    nodes.set(nodeIds[i], {
      id: nodeIds[i],
      type: n.type,
      latticePos: [n.pos[0], n.pos[1]],
    });
  });
  const edges = new Map<
    string,
    { id: string; nodeA: string; nodeB: string; latticePoints: Array<[number, number]> }
  >();
  const adjacency = new Map<string, string[]>();
  for (const nid of nodeIds) adjacency.set(nid, []);
  fEdges.forEach((e, ei) => {
    const eid = `se${ei}`;
    const a = nodeIds[e.a];
    const b = nodeIds[e.b];
    edges.set(eid, {
      id: eid,
      nodeA: a,
      nodeB: b,
      latticePoints: [
        [fNodes[e.a].pos[0], fNodes[e.a].pos[1]],
        [fNodes[e.b].pos[0], fNodes[e.b].pos[1]],
      ],
    });
    adjacency.get(a)!.push(eid);
    adjacency.get(b)!.push(eid);
  });
  const strands: Strand[] = strandCycles.map((cyc) => ({
    edgeIds: cyc.edges.map((ei) => `se${ei}`),
    isClosed: true,
    nodes: [...cyc.nodes.map((ni) => nodeIds[ni]), nodeIds[cyc.nodes[0]]],
    pinned: def.pinned,
  }));

  const graph: TangleGraph = {
    nodes,
    edges,
    adjacency,
    strands,
    seed: 0,
    params: { gridSize: 0, weaveDensity: 0, turnBias: 0, randSeed: 0 },
  };
  assignOverUnder(graph);
  return graph;
}
